<body>
<div class="container">
  <h1>📝 Todo List</h1>
  <div class="input-row">
    <input type="text" id="todoInput" placeholder="What needs to be done?" autofocus>
    <button onclick="addTodo()">Add</button>
  </div>
  <div class="filters">
    <button class="active" onclick="setFilter('all')">All</button>
    <button onclick="setFilter('active')">Active</button>
    <button onclick="setFilter('completed')">Completed</button>
  </div>
  <ul class="todo-list" id="todoList"></ul>
</div>

<script>
  let todos = JSON.parse(localStorage.getItem('todos') || '[]');
  let filter = 'all';

  const todoInput = document.getElementById('todoInput');
  const todoList = document.getElementById('todoList');

  function save() { localStorage.setItem('todos', JSON.stringify(todos)); }

  function addTodo() {
    const text = todoInput.value.trim();
    if (!text) return;
    todos.push({ id: Date.now(), text, completed: false });
    todoInput.value = '';
    save();
    render();
  }

  function toggleTodo(id) {
    const t = todos.find(x => x.id === id);
    if (t) { t.completed = !t.completed; save(); render(); }
  }

  function deleteTodo(id) {
    todos = todos.filter(x => x.id !== id);
    save();
    render();
  }

  function setFilter(f) {
    filter = f;
    document.querySelectorAll('.filters button').forEach((b, i) => {
      b.classList.toggle('active', (i === 0 && f === 'all') || (i === 1 && f === 'active') || (i === 2 && f === 'completed'));
    });
    render();
  }

  function render() {
    const filtered = filter === 'all'
      ? todos
      : filter === 'active' ? todos.filter(t => !t.completed)
      : todos.filter(t => t.completed);

    if (filtered.length === 0) {
      todoList.innerHTML = '<li class="empty">No todos here yet!</li>';
      return;
    }

    todoList.innerHTML = '';
    filtered.forEach(t => {
      const li = document.createElement('li');
      li.className = t.completed ? 'completed' : '';
      li.innerHTML = `
        <input type="checkbox" ${t.completed ? 'checked' : ''} onchange="toggleTodo(${t.id})">
        <span class="text">${escapeHtml(t.text)}</span>
        <button class="delete-btn" onclick="deleteTodo(${t.id})" title="Delete">✕</button>
      `;
      todoList.appendChild(li);
    });
  }

  function escapeHtml(s) {
    return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  }

  todoInput.addEventListener('keydown', e => { if (e.key === 'Enter') addTodo(); });

  render();
</script>
</body>
